    });

    // Fill top performer table
    var tbody = document.querySelector('#topPerformerTable tbody');
    dimensions.forEach(function(d) {
      var row = tbody.insertRow();
      row.insertCell(0).textContent = dimLabels[d];
      row.insertCell(1).textContent = topPerformers[d].model;
      row.insertCell(2).textContent = topPerformers[d].type;
      row.insertCell(3).textContent = topPerformers[d][d];
    });

    var chartsBuilt = false;

    function getColors() {
      var isDark = document.documentElement.className === 'theme-dark';
      return {
        text: isDark ? '#EDEDED' : '#0f172a',
        textSecondary: isDark ? '#94a3b8' : '#64748b',
        border: isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)',
        surface: isDark ? '#141414' : '#FFFFFF',
        bg: isDark ? '#0A0A0A' : '#FAFAF9',
        types: isDark ? typeColorsDark : typeColors,
        isDark: isDark
      };
    }

    function buildChart() {
      if (chartsBuilt) return;
      var colors = getColors();

      var container = document.getElementById('chartContainer');
      var svg = d3.select('#pcChart');
      svg.selectAll('*').remove();

      var margin = { top: 50, right: 60, bottom: 30, left: 60 };
      var width = container.clientWidth - margin.left - margin.right;
      var height = 600 - margin.top - margin.bottom;

      svg.attr('width', width + margin.left + margin.right);
      svg.attr('height', height + margin.top + margin.bottom);

      var g = svg.append('g').attr('transform', 'translate(' + margin.left + ',' + margin.top + ')');

      // Scales for each dimension
      var yScales = {};
      dimensions.forEach(function(d) {
        var extent = d3.extent(rawData, function(car) { return car[d]; });
        var pad = (extent[1] - extent[0]) * 0.08;
        yScales[d] = d3.scaleLinear()
          .domain([Math.max(0, extent[0] - pad), Math.min(100, extent[1] + pad)])
          .range([height, 0]);
      });

      var xScale = d3.scalePoint()
        .domain(dimensions)
        .range([0, width]);

      // Background bands for type clustering emphasis
      // Highlight the trade-off zones: power-fuel, price-resale
      var bandZones = [
        { from: "power", to: "fuel_efficiency", label: "Power vs\nEfficiency\nTrade-off" },
        { from: "price_score", to: "resale_value", label: "Price vs\nResale\nCrossing" }
      ];

      bandZones.forEach(function(zone) {
        var x1 = xScale(zone.from);
        var x2 = xScale(zone.to);
        g.append('rect')
          .attr('x', Math.min(x1, x2) + 8)
          .attr('y', 4)
          .attr('width', Math.abs(x2 - x1) - 16)
          .attr('height', height - 8)
          .attr('fill', colors.isDark ? 'rgba(251,191,36,0.04)' : 'rgba(217,119,6,0.04)')
          .attr('rx', 4);
      });

      // Draw polylines
      var lineGenerator = d3.line()
        .x(function(d) { return xScale(d.dimension); })
        .y(function(d) { return yScales[d.dimension](d.value); });

      var carLines = rawData.map(function(car) {
        return dimensions.map(function(d) {
          return { dimension: d, value: car[d] };
        });
      });

      // Draw lines with opacity
      g.selectAll('.car-line')
        .data(carLines)
        .enter()
        .append('path')
        .attr('d', lineGenerator)
        .attr('fill', 'none')
        .attr('stroke', function(d, i) { return colors.types[rawData[i].type]; })
        .attr('stroke-width', 1.6)
        .attr('stroke-opacity', 0.55)
        .attr('stroke-linejoin', 'round')
        .on('mouseover', function(event, d) {
          var idx = carLines.indexOf(d);
          d3.select(this).attr('stroke-width', 3.5).attr('stroke-opacity', 1);
          // Show tooltip
          var car = rawData[idx];
          var tip = d3.select('#tooltip');
          tip.style('display', 'block')
            .html('<strong>' + car.model + '</strong><br><span style="color:' + (colors.isDark ? '#94a3b8' : '#64748b') + '">' + car.type + '</span>');
        })
        .on('mousemove', function(event) {
          d3.select('#tooltip')
            .style('left', (event.pageX + 14) + 'px')
            .style('top', (event.pageY - 40) + 'px');
        })
        .on('mouseout', function(event, d) {
          d3.select(this).attr('stroke-width', 1.6).attr('stroke-opacity', 0.55);
          d3.select('#tooltip').style('display', 'none');
        });

      // Top performer highlights — bright stars on each axis
      dimensions.forEach(function(d) {
        var topCar = topPerformers[d];
        var cx = xScale(d);
        var cy = yScales[d](topCar[d]);
        var tc = colors.types[topCar.type];

        // Glow circle
        g.append('circle')
          .attr('cx', cx).attr('cy', cy).attr('r', 8)
          .attr('fill', 'none').attr('stroke', tc)
          .attr('stroke-width', 2.5).attr('stroke-opacity', 0.9);

        g.append('circle')
          .attr('cx', cx).attr('cy', cy).attr('r', 4.5)
          .attr('fill', tc).attr('stroke', '#fff')
          .attr('stroke-width', 1.5);

        // Label
        g.append('text')
          .attr('x', cx).attr('y', cy - 14)
          .attr('text-anchor', 'middle')
          .attr('font-size', '10px').attr('font-weight', '700')
          .attr('fill', tc)
          .attr('font-family', 'Inter, sans-serif')
          .text(topCar.model);
      });

      // Draw axes
      dimensions.forEach(function(d) {
        var x = xScale(d);
        // Axis line
        g.append('line')
          .attr('x1', x).attr('x2', x)
          .attr('y1', 0).attr('y2', height)
          .attr('stroke', colors.border)
          .attr('stroke-width', 1.5);

        // Tick marks
        var scale = yScales[d];
        var ticks = scale.ticks(5);
        ticks.forEach(function(t) {
          g.append('line')
            .attr('x1', x - 5).attr('x2', x + 5)
            .attr('y1', scale(t)).attr('y2', scale(t))
            .attr('stroke', colors.border)
            .attr('stroke-width', 1);
          g.append('text')
            .attr('x', x - 8).attr('y', scale(t))
            .attr('dy', '0.32em')
            .attr('text-anchor', 'end')
            .attr('font-size', '10px')
            .attr('fill', colors.textSecondary)
            .attr('font-family', 'Inter, sans-serif')
            .text(t);
        });
      });

      // Axis labels
      g.selectAll('.axis-label')
        .data(dimensions)
        .enter()
        .append('text')
        .attr('class', 'axis-label')
        .attr('x', function(d) { return xScale(d); })
        .attr('y', height + 24)
        .attr('text-anchor', 'middle')
        .attr('font-size', '12px')
        .attr('font-weight', '600')
        .attr('fill', colors.text)
        .attr('font-family', 'Inter, sans-serif')
        .text(function(d) { return dimLabels[d]; });

      chartsBuilt = true;
    }

    function onThemeChange() {
      // Remove old tooltip if exists
      d3.select('#tooltip').remove();
      chartsBuilt = false;
      buildChart();
    }

    // Add tooltip div
    d3.select('body').append('div')
      .attr('id', 'tooltip')
      .style('position', 'absolute')
      .style('display', 'none')
      .style('background', 'var(--surface)')
      .style('color', 'var(--text)')
      .style('border', '1px solid var(--border)')
      .style('border-radius', '8px')
      .style('padding', '10px 14px')
      .style('font-size', '13px')
      .style('font-family', 'Inter, sans-serif')
      .style('pointer-events', 'none')
      .style('z-index', '9998')
      .style('box-shadow', '0 4px 16px rgba(0,0,0,0.12)')
      .style('line-height', '1.5');

    window.addEventListener('resize', function() { chartsBuilt = false; buildChart(); });
    window.addEventListener('load', buildChart);
  </script>
</body>
</html>
