const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1400, height: 1100 } });

  page.on('console', msg => console.log('CONSOLE:', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('PAGE ERROR:', err.message));

  const htmlPath = 'file://' + require('path').resolve('/app/output/parallel_coords.html');
  console.log('Loading:', htmlPath);
  await page.goto(htmlPath, { waitUntil: 'networkidle', timeout: 15000 });

  // Check if D3 loaded
  const d3Loaded = await page.evaluate(() => typeof d3 !== 'undefined');
  console.log('D3 loaded:', d3Loaded);

  // Check if SVG exists
  const svgExists = await page.evaluate(() => !!document.getElementById('pcChart'));
  console.log('SVG element exists:', svgExists);

  // Check for any JS errors
  const bodyText = await page.evaluate(() => document.body.innerText.substring(0, 500));
  console.log('Body text sample:', bodyText);

  await page.waitForTimeout(2000);

  // Try to manually call buildChart
  await page.evaluate(() => {
    if (typeof buildChart === 'function') {
      chartsBuilt = false;
      buildChart();
    }
  });

  await page.waitForTimeout(500);

  const svgContent = await page.evaluate(() => {
    var svg = document.getElementById('pcChart');
    return svg ? svg.innerHTML.substring(0, 200) : 'no svg';
  });
  console.log('SVG content:', svgContent);

  await page.screenshot({ path: '/app/output/result.png', fullPage: true, type: 'png' });
  console.log('Screenshot saved');
  await browser.close();
})();
